css:
@page {
	size: A4 portrait;
	margin: 8mm;
}

* {
	box-sizing: border-box;
}

body {
	font-family: "Noto Sans", "Noto Naskh Arabic", Arial, sans-serif;
	font-size: 11px;
	color: #111827;
	margin: 0;
	padding: 0;
}

.print-card {
	border: 1px solid #cbd5e1;
	border-radius: 14px;
	overflow: hidden;
	background: #fff;
}

.header-band {
	background: linear-gradient(135deg, #0f2e6d 0%, #1f5fbf 100%);
	color: #fff;
	padding: 14px 18px 10px;
	text-align: center;
}

.header-band .title-ar {
	font-size: 26px;
	font-weight: 700;
	line-height: 1.2;
	direction: rtl;
}

.header-band .title-en {
	font-size: 18px;
	font-weight: 700;
	margin-top: 3px;
	letter-spacing: 0.2px;
}

.company-line {
	margin-top: 6px;
	font-size: 11px;
	opacity: 0.95;
}

.content-wrap {
	padding: 10px 14px 14px;
}

.meta-table,
.check-table,
.sign-table {
	width: 100%;
	border-collapse: collapse;
}

.meta-table th,
.meta-table td,
.check-table th,
.check-table td,
.sign-table th,
.sign-table td {
	border: 1px solid #94a3b8;
	padding: 6px 7px;
	vertical-align: middle;
}

.meta-table th,
.check-table th,
.sign-table th {
	background: #dbeafe;
	color: #0f172a;
	font-weight: 700;
}

.meta-table td.label,
.meta-table td.label-ar {
	background: #eff6ff;
	font-weight: 700;
	width: 13%;
}

.meta-table td.value {
	width: 12%;
}

.label-ar,
.text-ar,
.section-head .ar {
	direction: rtl;
	text-align: right;
	font-family: "Noto Naskh Arabic", "Noto Sans", Arial, sans-serif;
}

.section-box {
	margin-top: 10px;
	page-break-inside: avoid;
}

.section-head {
	background: #eff6ff;
	border: 1px solid #93c5fd;
	border-bottom: 0;
	padding: 7px 10px;
	font-weight: 700;
	display: flex;
	justify-content: space-between;
	align-items: center;
	gap: 10px;
}

.section-head .en {
	font-size: 17px;
}

.section-head .ar {
	font-size: 17px;
}

.check-table th {
	text-align: center;
}

.check-table td.item-cell {
	width: 39%;
}

.check-table td.mark-cell {
	width: 12%;
	text-align: center;
	font-weight: 700;
	font-size: 13px;
}

.check-table td.notes-cell {
	width: 25%;
}

.item-en {
	font-weight: 600;
}

.item-ar {
	display: block;
	margin-top: 2px;
	font-size: 10px;
	direction: rtl;
	text-align: right;
}

.mark-yes {
	color: #166534;
}

.mark-warn {
	color: #b45309;
}

.mark-no {
	color: #b91c1c;
}

.summary-box {
	margin-top: 10px;
	border: 1px solid #94a3b8;
	padding: 8px 10px;
	border-radius: 8px;
}

.summary-line {
	display: flex;
	justify-content: space-between;
	gap: 14px;
	font-weight: 700;
}

.summary-status {
	padding: 2px 8px;
	border-radius: 999px;
	border: 1px solid #94a3b8;
}

.notes-box {
	margin-top: 8px;
	border: 1px dashed #94a3b8;
	min-height: 42px;
	padding: 6px 8px;
}

.declaration-box {
	margin-top: 10px;
	font-size: 10.5px;
	border-top: 1px dashed #94a3b8;
	padding-top: 8px;
}

.sign-table {
	margin-top: 10px;
}

.sign-box {
	height: 60px;
}

.footer-line {
	margin-top: 10px;
	text-align: center;
	font-size: 10px;
	color: #334155;
}

.small-muted {
	font-size: 10px;
	color: #475569;
}

.center {
	text-align: center;
}
